public static async Task<Dictionary<int, int>> GetViewsPerBlogAsync(
    BlogContext context, string searchTerm, CancellationToken cancellationToken)
{
    var query =
        from post in context.Posts
        where post.Title.Contains(searchTerm)
        group post.Views by post.BlogId into g
        select new { BlogId = g.Key, TotalViews = g.Sum() };

    return await query.ToDictionaryAsync(x => x.BlogId, x => x.TotalViews, cancellationToken);
}
```

